// Sword Quest — preserved from the original working game.js

// ---------- HERO: SMOOTH ATTACK / JUMP / MOVEMENT ANIMATION ----------
  // Real frames extracted from supplied hero footage, background removed to
  // transparent and cropped/aligned to a shared box per-set (same pipeline as
  // the bat/Thornwalker) so nothing jitters between frames. Three independent
  // sets are swapped in based on what the player is doing:
  //   attacking          -> hero_attack (8 frames, plays once per swing)
  //   airborne (jump/fall) -> hero_jump (8 frames, chosen by vertical speed)
  //   moving on ground    -> hero_movement (8 frames, loops)
  //   idle                -> hero_movement frame 0 (held)
  const HERO_ATTACK_FRAME_COUNT = 8;
  const HERO_JUMP_FRAME_COUNT = 8;
  const HERO_MOVE_FRAME_COUNT = 8;
  const HERO_MOVE_FRAME_HOLD = 4; // engine frames each movement pose is held for
  const HERO_DRAW_SCALE = 2.15;   // sprite height relative to player.h, matches bat/thornwalker scale convention

  const heroAttackImages = Array.from({length:HERO_ATTACK_FRAME_COUNT}, (_,i)=>{
    const img = new Image();
    img.decoding = 'async';
    img.src = `assets/hero_attack/hero_attack_${String(i).padStart(2,'0')}.png`;
    return img;
  });

  const heroJumpImages = Array.from({length:HERO_JUMP_FRAME_COUNT}, (_,i)=>{
    const img = new Image();
    img.decoding = 'async';
    img.src = `assets/hero_jump/hero_jump_${String(i).padStart(2,'0')}.png`;
    return img;
  });

  const heroMoveImages = Array.from({length:HERO_MOVE_FRAME_COUNT}, (_,i)=>{
    const img = new Image();
    img.decoding = 'async';
    img.src = `assets/hero_movement/hero_movement_${String(i).padStart(2,'0')}.png`;
    return img;
  });

  // Small blue/gold spark-burst sprite shown on a successful parry, in place
  // of the old plain expanding ring. Plays once across PARRY_SUCCESS_FLASH.
  const PARRY_FLASH_FRAME_COUNT = 5;
  // Supplied long-range fireball sprite. The checkerboard from the source
  // image has been removed so only the cyan flame remains transparent.
  const fireballImg = new Image();
  fireballImg.decoding = 'async';
  fireballImg.src = 'assets/fireball.png';

  const parryFlashImages = Array.from({length:PARRY_FLASH_FRAME_COUNT}, (_,i)=>{
    const img = new Image();
    img.decoding = 'async';
    img.src = `assets/parry_flash/parry_flash_${String(i).padStart(2,'0')}.png`;
    return img;
  });

  function heroAttackFrameIndex() {
    // attackTimer counts down from its starting value (set in updatePlayer)
    // to 0 over the course of the swing; map that countdown onto the frames
    // in forward order so the swing plays windup -> follow-through once.
    const total = 14; // matches player.attackTimer starting value
    const elapsed = Math.min(total, Math.max(0, total - player.attackTimer));
    const idx = Math.floor((elapsed/total) * HERO_ATTACK_FRAME_COUNT);
    return Math.min(HERO_ATTACK_FRAME_COUNT-1, idx);
  }

  function heroParryFrameIndex() {
    // Parry stance reuses the exact same swing frames as an attack (same
    // frame count, same countdown-based mapping) — see PARRY_DURATION in
    // 01_game_core.js, which is deliberately set to match the attack's
    // starting timer value below.
    const total = PARRY_DURATION;
    const elapsed = Math.min(total, Math.max(0, total - player.parryTimer));
    const idx = Math.floor((elapsed/total) * HERO_ATTACK_FRAME_COUNT);
    return Math.min(HERO_ATTACK_FRAME_COUNT-1, idx);
  }

  function heroJumpFrameIndex() {
    // Map vertical velocity to pose: strong upward velocity (just launched)
    // -> early frame, near-zero velocity (apex) -> middle frame, falling
    // -> later frame.
    const vyMin = -13, vyMax = 18;
    let t = (player.vy - vyMin) / (vyMax - vyMin);
    t = Math.max(0, Math.min(1, t));
    const idx = Math.floor(t * HERO_JUMP_FRAME_COUNT);
    return Math.min(HERO_JUMP_FRAME_COUNT-1, idx);
  }

  function heroMoveFrameIndex() {
    const phase = Math.floor(frameCount / HERO_MOVE_FRAME_HOLD);
    return phase % HERO_MOVE_FRAME_COUNT;
  }

  // ---------- HERO: IDLE "BREATHING" LOOP ----------
  // No dedicated idle frames were supplied, so we reuse the calmest part of
  // the movement set -- frames 0-5, where the pose barely shifts and only
  // the flame flickers -- and ping-pong through them slowly (forward then
  // backward) for a subtle breathing/sway effect. Frames 6-7 (the bright
  // flare burst) are deliberately excluded here since they'd read as a
  // sudden flash rather than a calm idle.
  const HERO_IDLE_FRAME_COUNT = 6;      // uses heroMoveImages[0..5]
  const HERO_IDLE_FRAME_HOLD = 11;      // slower hold than movement for a gentle breathing pace
  const HERO_IDLE_PINGPONG_LEN = (HERO_IDLE_FRAME_COUNT - 1) * 2; // 10-step forward+back cycle

  function heroIdleFrameIndex() {
    const phase = Math.floor(frameCount / HERO_IDLE_FRAME_HOLD) % HERO_IDLE_PINGPONG_LEN;
    return phase < HERO_IDLE_FRAME_COUNT ? phase : HERO_IDLE_PINGPONG_LEN - phase;
  }

  function heroGetSprite() {
    let img = null;
    if (player.attacking) {
      img = heroAttackImages[heroAttackFrameIndex()];
    } else if (player.parrying) {
      // Same sprite set as the attack swing — see heroParryFrameIndex().
      img = heroAttackImages[heroParryFrameIndex()];
    } else if (!player.onGround) {
      img = heroJumpImages[heroJumpFrameIndex()];
    } else if (player.moving) {
      img = heroMoveImages[heroMoveFrameIndex()];
    }
    if (img && img.complete && img.naturalWidth > 0) return img;
    // idle: gentle breathing loop (or not-yet-loaded fallback before any
    // frame has finished loading, in which case frame 0 just holds still)
    const idleImg = heroMoveImages[heroIdleFrameIndex()];
    if (idleImg && idleImg.complete && idleImg.naturalWidth > 0) return idleImg;
    const fallbackImg = heroMoveImages[0];
    if (fallbackImg && fallbackImg.complete && fallbackImg.naturalWidth > 0) return fallbackImg;
    return null;
  }

  function batFlyFrameIndex(en) {
    // Offset by each bat's own position so a sky full of bats doesn't all
    // flap in lockstep.
    const phase = Math.floor((frameCount + (en.x||0)) / BAT_FLY_FRAME_HOLD);
    return phase % BAT_FLY_FRAME_COUNT;
  }

  function batGetVisualImage(en) {
    const img = batFlyImages[batFlyFrameIndex(en)];
    if(img && img.complete && img.naturalWidth > 0) return img;
    return null;
  }

  function thornIdleFrameIndex(en) {
    // Give each enemy its own phase so a room full of Thornwalkers doesn't
    // all sway in lockstep.
    const phase = Math.floor((frameCount + (en.homeX||0)) / THORN_IDLE_FRAME_HOLD);
    const span = THORN_IDLE_FRAME_COUNT - 1;
    const cycle = span * 2;
    const pos = phase % cycle;
    return pos <= span ? pos : cycle - pos;
  }

  // Real frame (into thornIdleImages) used to pose the attack windup/strike/
  // recovery — see THORN_WIND_START_FRAME etc. above for why this reads from
  // the idle/run set instead of a dedicated attack sheet. Winding eases the
  // blade up to the raised peak; the first 60% of the swing sweeps it down
  // through the strike window; the rest is follow-through; cooldown eases
  // back toward a normal running pose so it blends into the ambient sway.
  function thornAttackVisualFrame(en) {
    if (en.state === 'winding') {
      const p = 1 - (en.wakeTimer / THORNWALKER_WAKE_FRAMES);
      return Math.round(THORN_WIND_START_FRAME + p * (THORN_STRIKE_PEAK_FRAME - THORN_WIND_START_FRAME));
    }
    if (en.state === 'swinging') {
      const p = 1 - (en.swingTimer / THORNWALKER_SWING_FRAMES);
      if (p < 0.6) {
        return Math.round(THORN_STRIKE_PEAK_FRAME + (p/0.6) * (THORN_STRIKE_END_FRAME - THORN_STRIKE_PEAK_FRAME));
      }
      const p2 = (p - 0.6) / 0.4;
      return Math.round(THORN_STRIKE_END_FRAME + p2 * (THORN_RECOVER_END_FRAME - THORN_STRIKE_END_FRAME));
    }
    if (en.state === 'cooldown') {
      const p = Math.min(1, (1 - (en.cooldownTimer / THORNWALKER_COOLDOWN_FRAMES)) * 2);
      return Math.round(THORN_RECOVER_END_FRAME + p * (THORN_WIND_START_FRAME - THORN_RECOVER_END_FRAME));
    }
    return null;
  }

  function thornGetVisualImage(en) {
    if(en.state === 'winding' || en.state === 'swinging' || en.state === 'cooldown'){
      const idx = thornAttackVisualFrame(en);
      if (idx != null) {
        const clamped = Math.max(0, Math.min(THORN_IDLE_FRAME_COUNT-1, idx));
        const img = thornIdleImages[clamped];
        if(img && img.complete && img.naturalWidth > 0) return img;
      }
    }
    // Idle / patrolling / chasing: cycle through the real animation frames
    // instead of a single frozen pose.
    const idleImg = thornIdleImages[thornIdleFrameIndex(en)];
    if(idleImg && idleImg.complete && idleImg.naturalWidth > 0) return idleImg;
    if(thornSourceIdle.complete && thornSourceIdle.naturalWidth > 0) return thornSourceIdle;
    return null;
  }

  // State changes are discrete. The in-between artwork itself provides the
  // smooth motion, so there is no crossfade and therefore no blur.
  function thornSetState(en,nextState) {
    if(en.state===nextState) return;
    en.state=nextState;
  }

  function statsFor(type){
    switch(type){
      case 'crawler': return {w:26,h:18,health:1,speed:2.6,dmg:8};
      case 'brute':   return {w:44,h:54,health:4,speed:0.75,dmg:18};
      case 'flyer':   return {w:28,h:22,health:2,speed:1.7,dmg:10};
      case 'thornwalker': return {w:22,h:56,health:3,speed:1.8,dmg:16};
      case 'snake':   return {w:125,h:70,health:SNAKE_HEALTH,speed:SNAKE_SPEED,dmg:SNAKE_DAMAGE};
      default:        return {w:28,h:36,health:2,speed:1.4,dmg:12}; // wraith
    }
  }

  function resetLevel(){
    enemies = enemyDefs.map(e => {
      const s = statsFor(e.type);
      return {
        x:e.x, y:e.y, w:s.w, h:s.h, vx:s.speed, range:e.range, health:s.health, maxHealth:s.health,
        alive:true, hitTimer:0, dir:1, type:e.type, dmg:s.dmg,
        state:'idle', wakeTimer:0, walkPhase:0, attackFlash:0, homeX:e.x,
        swingTimer:0, cooldownTimer:0, hasHit:false
      };
    });
    enemies = enemies.concat(flyerDefs.map(e => {
      const s = statsFor('flyer');
      return {
        x:e.x, y:e.y, baseY:e.y, amp:e.amp, phase:Math.random()*Math.PI*2,
        w:s.w, h:s.h, vx:s.speed, range:e.range, health:s.health, maxHealth:s.health,
        alive:true, hitTimer:0, dir:1, type:'flyer', dmg:s.dmg
      };
    }));
    gems = gemDefs.map(g => ({x:g.x, y:g.y, r:8, taken:false, bob:Math.random()*Math.PI*2}));
    particles = [];
    bossProjectiles = [];
    fireballs = [];
    boss = bossDef ? {
      x: bossDef.x, y: bossDef.y, w: bossDef.w, h: bossDef.h,
      health: bossDef.health, maxHealth: bossDef.maxHealth,
      vx: 0, vy: 0, phase: 1, lastPhase: 1, timer: 0, attackTimer: BOSS_EMERGE_FRAMES,
      hitFlash: 0, attackFlash: 0, defeated: false, dir: -1,
      emergeTimer: 0, emergeDuration: BOSS_EMERGE_FRAMES,
      introTimer: BOSS_INTRO_PAUSE_FRAMES,
      introComplete: false,
      voicePlayed: false,
      tauntTimer: 0,
      tauntIndex: 1,
      emerging: false,
      snakeAmbushTimer: SNAKE_FIRST_AMBUSH_DELAY,
      // The first snake enters from the right; every time it is killed,
      // the next spawn flips to the opposite side.
      snakeSpawnSide: 1,
      // Phase-2 floor-serpent attack state.
      phase2SnakeTimer: PHASE2_SNAKE_FIRST_DELAY,
      phase2SnakeAttack: null
    } : null;
    player = makePlayer();
    if(currentLevel === 3){
      player.x = 110;
      player.y = GROUND_Y-player.h;
    }
    player.score = carryScore;
    camX = 0;
    document.getElementById('gemTotal').textContent = gems.length;
    document.getElementById('gemCount').textContent = 0;
    document.getElementById('levelNum').textContent = currentLevel;
  }

  function goToLevel(n){
    carryScore = player.score;
    currentLevel = n;
    loadLevelData(currentLevel);
    resetLevel();
  }

  function restartRun(){
    currentLevel = 1;
    carryScore = 0;
    totalGemsCollected = 0;
    loadLevelData(currentLevel);
    resetLevel();
  }

  let camX = 0;
  let keys = {};
  let gameState = 'title'; // title | controls | playing | paused | win | lose | levelup
  let lastTime = 0;

  // pre-rendered grain texture for atmospheric post-process
  const grainCanvas = document.createElement('canvas');
  grainCanvas.width = 160; grainCanvas.height = 160;
  (function buildGrain(){
    const gctx = grainCanvas.getContext('2d');
    const idata = gctx.createImageData(160,160);
    for(let i=0;i<idata.data.length;i+=4){
      const v = Math.random()*255;
      idata.data[i]=v; idata.data[i+1]=v; idata.data[i+2]=v; idata.data[i+3]=255;
    }
    gctx.putImageData(idata,0,0);
  })();
  const grainPattern = ctx.createPattern(grainCanvas, 'repeat');

  // stone-ledge cutout used to render the regular level platforms
  const spikeTrapImg = new Image();
  spikeTrapImg.decoding = 'async';
  spikeTrapImg.src = "assets/spike_trap.png";

  // Gothic checkpoint gate artwork, shown at the level-goal marker in
  // place of the old vector flag. Background is already transparent.
  const checkpointGateImg = new Image();
  checkpointGateImg.decoding = 'async';
  checkpointGateImg.src = "assets/checkpoint_gate.png";

  // Falling-ball boss projectile artwork — red while it's still a threat
  // to the player, swapped to the blue version once it's been deflected
  // and is now a threat to the boss instead.
  const ballFallImg = new Image();
  ballFallImg.decoding = 'async';
  ballFallImg.src = "assets/ball_red.png";

  // Exact yellow parry-window artwork supplied for the falling ball.
  // It is shown only during the ideal timing window.
  const ballYellowImg = new Image();
  ballYellowImg.decoding = 'async';
  ballYellowImg.src = "assets/ball_yellow.png";

  const ballDeflectedImg = new Image();
  ballDeflectedImg.decoding = 'async';
  ballDeflectedImg.src = "assets/ball_blue.png";

  const platformImg = new Image();
  platformImg.src = "data:image/png;base64,";


  // Dedicated transparent platform artwork for the final boss arena.
  // Regular levels continue using the original platform asset above.
  const bossPlatformImg = new Image();
  bossPlatformImg.decoding = "async";
  bossPlatformImg.src = "assets/boss_platform.png";

  // Boss arena artwork. This is the uploaded 1568x588 image; the canvas is
  // 1200x450 (the same 8:3 aspect ratio), so the complete image is shown.
  const bossBgImage = new Image();
  bossBgImage.decoding = 'async';
  bossBgImage.src = "assets/boss_level.webp";

  // Bottom-screen boss health HUD artwork supplied for the Cathedral Warden.
  const bossHealthHudImg = new Image();
  bossHealthHudImg.decoding = "async";
  bossHealthHudImg.src = "assets/boss_health_hud.png";
  // Final boss animation: 160 frames per phase.
  const BOSS_FRAME_COUNT = 160;
  const BOSS_FRAME_HOLD = 2;
  const BOSS_DRAW_H = 286;

  const bossPhaseImages = {
    1: Array.from({length:BOSS_FRAME_COUNT}, (_,i)=>{
      const img = new Image();
      img.decoding = 'async';
      img.src = `assets/boss_phase1_sprite/boss_${String(i).padStart(3,'0')}.webp`;
      return img;
    }),
    2: Array.from({length:BOSS_FRAME_COUNT}, (_,i)=>{
      const img = new Image();
      img.decoding = 'async';
      img.src = `assets/boss_phase2_sprite/boss_${String(i).padStart(3,'0')}.webp`;
      return img;
    })
  };

  function bossFrameIndex() {
    return Math.floor(frameCount / BOSS_FRAME_HOLD) % BOSS_FRAME_COUNT;
  }

  function bossGetVisualImage() {
    const phaseImages = bossPhaseImages[boss && boss.phase === 2 ? 2 : 1];
    const img = phaseImages[bossFrameIndex()];
    if(img && img.complete && img.naturalWidth > 0) return img;
    const fallback = phaseImages[0];
    if(fallback && fallback.complete && fallback.naturalWidth > 0) return fallback;
    return null;
  }

  // uploaded gothic cathedral artwork used as the scrolling background
  const bgImage = new Image();
  bgImage.src = "data:image/jpeg;base64,";
  const bg2Image = new Image();
  bg2Image.src = "data:image/jpeg;base64,";
